type Product = { id: string; sku: string; barcode: string; name: string; price: number; cost: number; stock: number; type: ProductType; capitalSource?: CapitalSource; depreciation?: number; buildingCost?: number };
type CartItem = { productId: string; qty: number; price: number };
type TransactionItem = { productId: string; name: string; qty: number; price: number; cost: number; type: ProductType };
type Transaction = { noNota: string; date: string; customer: string; address: string; phone: string; items: TransactionItem[]; subtotal: number; discount: number; tax: number; total: number; jasaTotal: number; spareTotal: number; hppTotal: number; paymentMethod: PaymentMethod; paid: number; change: number; warrantyCode: string };
type FailedScanKind = "not-found" | "out-of-stock";
export type FailedScanRecord = { id: string; value: string; kind: FailedScanKind; productName?: string; timestamp: string; count: number };
export const upsertFailedScanRecord = (previous: FailedScanRecord[], entry: Omit<FailedScanRecord, "id" | "timestamp" | "count">, now = new Date()) => { const existing = previous.find(item => item.value === entry.value && item.kind === entry.kind); const next = existing ? previous.map(item => item === existing ? { ...item, productName: entry.productName || item.productName, timestamp: now.toISOString(), count: item.count + 1 } : item) : [{ ...entry, id: `${entry.kind}-${entry.value}-${now.getTime()}`, timestamp: now.toISOString(), count: 1 }, ...previous]; return next.slice(0, 100); };
export type Account = { code: string; name: string; type: AccountType; balance: number };
export function upsertCustomAccount(previous: Account[], account: Account, originalCode: string | null) {
  return originalCode ? previous.map(entry => entry.code === originalCode ? account : entry) : [...previous, account];
}
export function removeCustomAccount(previous: Account[], code: string) {
  return previous.filter(entry => entry.code !== code);
}
type PrinterSettings = { size: "58mm" | "80mm" | "A4"; headerText: string; footerText: string; warrantyText: string; nib: string; address: string; phone: string; showLogo: boolean; bluetoothDeviceId?: string; bluetoothDeviceName?: string };
type BluetoothPrinterDevice = { id: string; name?: string };
type BluetoothPrinterNavigator = Navigator & { bluetooth?: { requestDevice: (options: { acceptAllDevices: boolean; optionalServices: string[] }) => Promise<BluetoothPrinterDevice> } };
export async function discoverBluetoothPrinter() {
  const bluetooth = typeof navigator === "undefined" ? undefined : (navigator as BluetoothPrinterNavigator).bluetooth;
  if (!bluetooth) throw new Error("Bluetooth Web tidak didukung. Gunakan Chrome Android terbaru atau printer Wi-Fi.");
  const device = await bluetooth.requestDevice({ acceptAllDevices: true, optionalServices: ["000018f0-0000-1000-8000-00805f9b34fb"] });
  return { id: device.id, name: device.name || "Printer Bluetooth" };
}
