  const [failedScans, setFailedScans] = useState<FailedScanRecord[]>(() => readStored("anton_failed_scans_v22", []));
  const [stockCount, setStockCount] = useState<Record<string, string>>(() => readStored("anton_opname_v22", {}));
  const applyReportRange = (range: { from: string; to: string }) => { setReportLoading(true); window.setTimeout(() => { setReportPeriodFrom(range.from); setReportPeriodTo(range.to); setReportLoading(false); }, 180); };
  const applyReportDate = (setter: (value: string) => void, value: string) => { setReportLoading(true); window.setTimeout(() => { setter(value); setReportLoading(false); }, 180); };
  const runReportExport = (kind: "excel" | "pdf", action: () => void, successMessage = "Laporan berhasil diproses.") => { if (reportExporting) return; setReportExporting(kind); window.setTimeout(() => { action(); if (kind === "excel") toast.success(successMessage); setReportExporting(null); }, 120); };
  const [barcodeOpen, setBarcodeOpen] = useState(false);
  const [scannerOpen, setScannerOpen] = useState(false);
  const [productScannerOpen, setProductScannerOpen] = useState(false);
  const [barcodeInput, setBarcodeInput] = useState("");
  const [productBarcodeDraft, setProductBarcodeDraft] = useState("");
  const [productSkuDraft, setProductSkuDraft] = useState("");
  const [productSkuInput, setProductSkuInput] = useState("");
  const [productEditor, setProductEditor] = useState<Product | null | "new">(null);
  const [accountEditor, setAccountEditor] = useState<Account | null | "new">(null);
  const [receipt, setReceipt] = useState<Transaction | null>(null);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);
  const [installHelpOpen, setInstallHelpOpen] = useState(false);
  const [bluetoothStatus, setBluetoothStatus] = useState<"idle" | "scanning" | "connected" | "unsupported" | "error">("idle");
  useEffect(() => { if (productEditor === "new") setProductSkuInput(productSkuDraft); else if (productEditor) setProductSkuInput(productEditor.sku); else setProductSkuInput(""); }, [productEditor, productSkuDraft]);
  const [isInstalled, setIsInstalled] = useState(() => typeof window !== "undefined" && (window.matchMedia?.("(display-mode: standalone)").matches || (navigator as Navigator & { standalone?: boolean }).standalone === true));
  const logoInput = useRef<HTMLInputElement>(null);

  useEffect(() => writeStored("anton_products_v22", products), [products]);
  useEffect(() => writeStored("anton_inventory_capital_adjustment_v22", inventoryCapitalAdjustment), [inventoryCapitalAdjustment]);
  useEffect(() => writeStored("anton_transactions_v22", transactions), [transactions]);
  useEffect(() => writeStored("anton_coa_v22", customAccounts), [customAccounts]);
  useEffect(() => writeStored("anton_printer_v22", printer), [printer]);
  useEffect(() => writeStored("anton_logo_v22", logo), [logo]);
  useEffect(() => writeStored("anton_opname_v22", stockCount), [stockCount]);
  useEffect(() => writeStored("anton_failed_scans_v22", failedScans), [failedScans]);
  useEffect(() => {
    const onBeforeInstallPrompt = (event: Event) => captureInstallPrompt(event, setInstallPrompt);
    const onAppInstalled = () => {
      handleAppInstalled(setInstallPrompt, () => setInstallHelpOpen(false), () => toast.success("Anton Service POS berhasil dipasang."));
      setIsInstalled(true);
    };
    window.addEventListener("beforeinstallprompt", onBeforeInstallPrompt);
    window.addEventListener("appinstalled", onAppInstalled);
    if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => undefined);
    return () => {
      window.removeEventListener("beforeinstallprompt", onBeforeInstallPrompt);
      window.removeEventListener("appinstalled", onAppInstalled);
    };
  }, []);

  const totals = useMemo(() => summarizeTransactionTotals(transactions), [transactions]);
  const { serviceNetRevenue, spareNetRevenue } = totals;
  const accountBase = useMemo<Account[]>(() => {
    const inventory = totalInventoryValue(products);
    const openingInventory = totalInventoryValue(seedProducts);
    const funding = calculateCapitalSourceBalances(products);
    const cash = OPENING_CASH + totals.cash - funding.Kas, { bank, receivables, serviceRevenue, spareRevenue, serviceNetRevenue, spareNetRevenue, hpp, salesDiscount, taxPayable, expenseTotal } = totals;
    const toolDepreciation = totalToolDepreciation(products);
    const buildingCost = totalBuildingCost(products);
    const reconciledInventoryCapital = calculateReconciledInventoryCapital(products, transactions, openingInventory);
    const modalAccountBalance = calculateModalAccountBalance(products, transactions, openingInventory);
    return [
      { code: "101", name: "Kas", type: "Aktiva", balance: cash }, { code: "102", name: "Piutang Usaha", type: "Aktiva", balance: receivables - funding.Piutang },
      { code: "103", name: "Persediaan Barang", type: "Aktiva", balance: inventory }, { code: "104", name: "Bank / QRIS", type: "Aktiva", balance: bank - funding.Bank - funding.QRIS }, { code: "105", name: "Akumulasi Penyusutan Alat", type: "Aktiva", balance: -toolDepreciation }, { code: "106", name: "Biaya Gedung", type: "Aktiva", balance: -buildingCost },
      { code: "201", name: "Hutang Usaha", type: "Pasiva", balance: funding.Hutang }, { code: "202", name: "Hutang Bank", type: "Pasiva", balance: 0 }, { code: "203", name: "Hutang Pajak", type: "Pasiva", balance: taxPayable },
      { code: "301", name: "Modal", type: "Modal", balance: modalAccountBalance - nonModalCapitalFunding(products) }, { code: "401", name: "Pendapatan Jasa", type: "Pendapatan", balance: serviceRevenue },
      { code: "402", name: "Pendapatan Penjualan", type: "Pendapatan", balance: spareRevenue }, { code: "403", name: "Diskon", type: "Pendapatan", balance: salesDiscount },
      { code: "501", name: "Beban Operasional", type: "Beban", balance: expenseTotal }, { code: "502", name: "HPP", type: "Beban", balance: hpp }, { code: "503", name: "Penyusutan Alat", type: "Beban", balance: toolDepreciation }, { code: "504", name: "Biaya Gedung", type: "Beban", balance: buildingCost },
    ];
  }, [products, transactions, inventoryCapitalAdjustment, totals]);
  const accounts = useMemo(() => [...accountBase, ...customAccounts.filter(account => !accountBase.some(base => base.code === account.code))], [accountBase, customAccounts]);
  const reportTransactions = useMemo(() => transactions.filter(transaction => transactionMatchesPeriod(transaction.date, reportPeriodFrom, reportPeriodTo)), [transactions, reportPeriodFrom, reportPeriodTo]);
  const reportSystemBalances = useMemo(() => calculateSystemAccountBalances(products, reportTransactions, totalInventoryValue(seedProducts)), [products, reportTransactions]);
  const reportAccounts = useMemo(() => accounts.map(account => reportSystemBalances[account.code] === undefined ? account : { ...account, balance: reportSystemBalances[account.code] }), [accounts, reportSystemBalances]);
  // Neraca adalah posisi kumulatif sampai tanggal akhir, bukan hanya aktivitas di dalam filter periode.
  const reportBalanceTransactions = useMemo(() => transactionsThroughDate(transactions, reportPeriodTo), [transactions, reportPeriodTo]);
  const reportBalanceSystemBalances = useMemo(() => calculateSystemAccountBalances(products, reportBalanceTransactions, totalInventoryValue(seedProducts)), [products, reportBalanceTransactions]);
  const reportBalanceAccounts = useMemo(() => accounts.map(account => reportBalanceSystemBalances[account.code] === undefined ? account : { ...account, balance: reportBalanceSystemBalances[account.code] }), [accounts, reportBalanceSystemBalances]);
  const reportAssetTotal = reportAccounts.filter(account => account.type === "Aktiva").reduce((sum, account) => sum + account.balance, 0);
  const reportLiabilityTotal = reportAccounts.filter(account => account.type === "Pasiva").reduce((sum, account) => sum + account.balance, 0);
  const reportRevenueTotal = reportAccounts.filter(account => account.type === "Pendapatan").reduce((sum, account) => sum + account.balance, 0);
  const reportExpenseTotal = reportAccounts.filter(account => account.type === "Beban").reduce((sum, account) => sum + account.balance, 0);
  const reportNetIncome = reportRevenueTotal - reportExpenseTotal;
  const reportEquityTotal = reportAccounts.filter(account => account.type === "Modal").reduce((sum, account) => sum + account.balance, 0);
  const reportTotalLiabilityEquity = reportLiabilityTotal + reportEquityTotal + reportNetIncome;
  const reportBalanceDifference = reportAssetTotal - reportTotalLiabilityEquity;
  const reportBalanceAssetTotal = reportBalanceAccounts.filter(account => account.type === "Aktiva").reduce((sum, account) => sum + account.balance, 0);
  const reportBalanceLiabilityTotal = reportBalanceAccounts.filter(account => account.type === "Pasiva").reduce((sum, account) => sum + account.balance, 0);
  const reportBalanceRevenueTotal = reportBalanceAccounts.filter(account => account.type === "Pendapatan").reduce((sum, account) => sum + account.balance, 0);
  const reportBalanceExpenseTotal = reportBalanceAccounts.filter(account => account.type === "Beban").reduce((sum, account) => sum + account.balance, 0);
  const reportBalanceNetIncome = reportBalanceRevenueTotal - reportBalanceExpenseTotal;
  const reportBalanceEquityTotal = reportBalanceAccounts.filter(account => account.type === "Modal").reduce((sum, account) => sum + account.balance, 0);
  const reportBalanceTotalLiabilityEquity = reportBalanceLiabilityTotal + reportBalanceEquityTotal + reportBalanceNetIncome;
  const reportBalanceSheetDifference = reportBalanceAssetTotal - reportBalanceTotalLiabilityEquity;
  const reportPeriodPrinter = { ...printer, headerText: `${printer.headerText} · Periode ${reportPeriodFrom || "awal"} s/d ${reportPeriodTo || "sekarang"}` };
  const assetTotal = accounts.filter(account => account.type === "Aktiva").reduce((sum, account) => sum + account.balance, 0);
  const liabilityTotal = accounts.filter(account => account.type === "Pasiva").reduce((sum, account) => sum + account.balance, 0);
  const revenueTotal = accounts.filter(account => account.type === "Pendapatan").reduce((sum, account) => sum + account.balance, 0);
  const netRevenueTotal = serviceNetRevenue + spareNetRevenue;
  const expenseTotal = accounts.filter(account => account.type === "Beban").reduce((sum, account) => sum + account.balance, 0);
  const netIncome = revenueTotal - expenseTotal;
  const accountValue = (code: string) => accounts.find(account => account.code === code)?.balance || 0;
  const equityTotal = accounts.filter(account => account.type === "Modal").reduce((sum, account) => sum + account.balance, 0);
  const openingInventory = totalInventoryValue(seedProducts);
  const reconciledInventoryCapital = calculateReconciledInventoryCapital(products, transactions, openingInventory);
  const inventoryCapitalBalance = calculateInventoryCapitalBalance(products, transactions, openingInventory);
  const totalLiabilityEquity = liabilityTotal + equityTotal + netIncome;
  const balanceDifference = assetTotal - totalLiabilityEquity;
